import {
  pgTable,
  pgEnum,
  text,
  timestamp,
  boolean,
  integer,
  smallint,
  uuid,
  index,
  uniqueIndex,
  jsonb,
  primaryKey,
} from "drizzle-orm/pg-core";

/* ------------------------------------------------------------------ */
/* Auth tables — shape generated by better-auth's Drizzle generator.   */
/* ------------------------------------------------------------------ */

export const user = pgTable("user", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  email: text("email").notNull().unique(),
  emailVerified: boolean("email_verified").default(false).notNull(),
  image: text("image"),
  createdAt: timestamp("created_at").defaultNow().notNull(),
  updatedAt: timestamp("updated_at")
    .defaultNow()
    .$onUpdate(() => new Date())
    .notNull(),
});

export const session = pgTable(
  "session",
  {
    id: text("id").primaryKey(),
    expiresAt: timestamp("expires_at").notNull(),
    token: text("token").notNull().unique(),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .$onUpdate(() => new Date())
      .notNull(),
    ipAddress: text("ip_address"),
    userAgent: text("user_agent"),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
  },
  (t) => [index("session_userId_idx").on(t.userId)],
);

export const account = pgTable(
  "account",
  {
    id: text("id").primaryKey(),
    accountId: text("account_id").notNull(),
    providerId: text("provider_id").notNull(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    accessToken: text("access_token"),
    refreshToken: text("refresh_token"),
    idToken: text("id_token"),
    accessTokenExpiresAt: timestamp("access_token_expires_at"),
    refreshTokenExpiresAt: timestamp("refresh_token_expires_at"),
    scope: text("scope"),
    password: text("password"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (t) => [index("account_userId_idx").on(t.userId)],
);

export const verification = pgTable(
  "verification",
  {
    id: text("id").primaryKey(),
    identifier: text("identifier").notNull(),
    value: text("value").notNull(),
    expiresAt: timestamp("expires_at").notNull(),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .defaultNow()
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (t) => [index("verification_identifier_idx").on(t.identifier)],
);

/* ------------------------------------------------------------------ */
/* Platform tables                                                     */
/* ------------------------------------------------------------------ */

export const goalEnum = pgEnum("learning_goal", [
  "work",
  "travel",
  "study",
  "migration",
  "business",
  "interview",
  "daily",
  "academic",
]);

export const levelEnum = pgEnum("cefr_level", ["A0", "A1", "A2", "B1", "B2", "C1", "C2"]);

export const uiLocaleEnum = pgEnum("ui_locale", ["ar", "en"]);

/**
 * Languages are data, not code: adding a language is an INSERT plus content,
 * never a rebuild. Speech fields drive which voice features are offered.
 */
export const languages = pgTable("languages", {
  code: text("code").primaryKey(), // ISO 639-1
  nameEn: text("name_en").notNull(),
  nameAr: text("name_ar").notNull(),
  nativeName: text("native_name").notNull(),
  glyph: text("glyph").notNull(),
  script: text("script").notNull(), // latin, cyrillic, han, kana, hangul, arabic
  direction: text("direction").notNull().default("ltr"),
  sttLocale: text("stt_locale"),
  ttsVoice: text("tts_voice"),
  pronunciationSupported: boolean("pronunciation_supported").notNull().default(false),
  isTarget: boolean("is_target").notNull().default(true),
  enabled: boolean("enabled").notNull().default(true),
  sortOrder: smallint("sort_order").notNull().default(0),
});

export const profiles = pgTable("profiles", {
  userId: text("user_id")
    .primaryKey()
    .references(() => user.id, { onDelete: "cascade" }),
  nativeLanguage: text("native_language").references(() => languages.code),
  uiLocale: uiLocaleEnum("ui_locale").notNull().default("ar"),
  onboardedAt: timestamp("onboarded_at"),
  createdAt: timestamp("created_at").defaultNow().notNull(),
  updatedAt: timestamp("updated_at")
    .defaultNow()
    .$onUpdate(() => new Date())
    .notNull(),
});

export const learningTracks = pgTable(
  "learning_tracks",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    targetLanguage: text("target_language")
      .notNull()
      .references(() => languages.code),
    goal: goalEnum("goal").notNull(),
    dailyMinutes: smallint("daily_minutes").notNull(),
    selfLevel: levelEnum("self_level").notNull(),
    /** Set by the placement test (Phase 2); null until taken. */
    placementLevel: levelEnum("placement_level"),
    isActive: boolean("is_active").notNull().default(false),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .defaultNow()
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (t) => [
    uniqueIndex("tracks_user_language_uq").on(t.userId, t.targetLanguage),
    index("tracks_user_idx").on(t.userId),
  ],
);

/**
 * Unified activity log. Dashboard numbers (minutes, XP, streak) are derived
 * from real rows here — never hard-coded.
 */
export const activityEvents = pgTable(
  "activity_events",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    trackId: uuid("track_id").references(() => learningTracks.id, { onDelete: "cascade" }),
    kind: text("kind").notNull(),
    durationSeconds: integer("duration_seconds").notNull().default(0),
    xp: integer("xp").notNull().default(0),
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
  },
  (t) => [index("activity_user_time_idx").on(t.userId, t.createdAt)],
);

/* ------------------------------------------------------------------ */
/* Phase 2: placement, skill levels, lessons                           */
/* ------------------------------------------------------------------ */

export const placementTests = pgTable(
  "placement_tests",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    trackId: uuid("track_id")
      .notNull()
      .references(() => learningTracks.id, { onDelete: "cascade" }),
    language: text("language").notNull(),
    selfLevel: levelEnum("self_level").notNull(),
    status: text("status").notNull().default("in_progress"), // in_progress | completed
    result: jsonb("result"),
    startedAt: timestamp("started_at", { withTimezone: true }).defaultNow().notNull(),
    completedAt: timestamp("completed_at", { withTimezone: true }),
  },
  (t) => [index("placement_user_track_idx").on(t.userId, t.trackId)],
);

export const placementResponses = pgTable(
  "placement_responses",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    testId: uuid("test_id")
      .notNull()
      .references(() => placementTests.id, { onDelete: "cascade" }),
    itemId: text("item_id").notNull(),
    skill: text("skill").notNull(),
    level: text("level").notNull(),
    correct: boolean("correct").notNull(),
    answer: smallint("answer").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
  },
  (t) => [uniqueIndex("placement_response_uq").on(t.testId, t.itemId)],
);

/** Current CEFR estimate per skill for a track. Updated by placement now, by lessons/AI later. */
export const skillLevels = pgTable(
  "skill_levels",
  {
    trackId: uuid("track_id")
      .notNull()
      .references(() => learningTracks.id, { onDelete: "cascade" }),
    skill: text("skill").notNull(),
    level: text("level").notNull(),
    source: text("source").notNull(), // placement | lessons | tutor
    updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow().notNull(),
  },
  (t) => [primaryKey({ columns: [t.trackId, t.skill] })],
);

export const lessonProgress = pgTable(
  "lesson_progress",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    lessonId: text("lesson_id").notNull(),
    bestScore: smallint("best_score").notNull(), // 0–100
    attempts: integer("attempts").notNull().default(1),
    completedAt: timestamp("completed_at", { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow().notNull(),
  },
  (t) => [uniqueIndex("lesson_progress_user_lesson_uq").on(t.userId, t.lessonId)],
);

/** Every graded answer. Feeds the error log and adaptive plan in later phases. */
export const exerciseAttempts = pgTable(
  "exercise_attempts",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    lessonId: text("lesson_id").notNull(),
    exerciseId: text("exercise_id").notNull(),
    tag: text("tag"),
    correct: boolean("correct").notNull(),
    answer: text("answer").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
  },
  (t) => [index("attempts_user_time_idx").on(t.userId, t.createdAt)],
);

export const authSchema = { user, session, account, verification };
